def transform(grid):
    """Find all complete 3x3 clusters, select the one with minimum cell value."""
    h, w = len(grid), len(grid[0])
    clusters = []

    for r in range(h-2):
        for c in range(w-2):
            block = [[grid[r+dr][c+dc] for dc in range(3)] for dr in range(3)]

            # Check if complete (all 9 cells non-zero)
            if all(cell != 0 for cell in block):
                clusters.append((r, c, block))

    if not clusters:
        return grid

    # Find cluster with minimum value
    best = None
    best_min = float('inf')
    for r, c, block in clusters:
        min_val = min(cell for row in block for cell in row)
        if min_val < best_min:
            best_min = min_val
            best = block

    return best
